<?php
namespace App\Services\DevOps;use App\Models\{ZigoDeployment,ZigoDevOpsRelease};use Illuminate\Support\Facades\DB;
final class ReleaseService {public function register(ZigoDeployment $deployment):ZigoDevOpsRelease{if($deployment->status!=='success')throw new \RuntimeException('Solo deployments exitosos generan releases.');return DB::transaction(function()use($deployment){ZigoDevOpsRelease::where('environment',$deployment->environment)->where('status','active')->update(['status'=>'superseded']);return ZigoDevOpsRelease::updateOrCreate(['deployment_id'=>$deployment->id],['environment'=>$deployment->environment,'branch'=>$deployment->branch,'commit_hash'=>$deployment->commit_hash,'package_sha256'=>$deployment->package_sha256,'status'=>'active','deployed_at'=>$deployment->finished_at??now(),'deployed_by_user_id'=>$deployment->approved_by_user_id,'files_fingerprint'=>$this->fingerprint($deployment),'metadata'=>['source'=>'deployment_executor']]);});}public function active(string $environment):?ZigoDevOpsRelease{return ZigoDevOpsRelease::with(['deployment','deployedBy'])->where('environment',$environment)->where('status','active')->latest('deployed_at')->first();}public function history(?string $environment=null){return ZigoDevOpsRelease::with(['deployment','deployedBy'])->when($environment,fn($q)=>$q->where('environment',$environment))->latest('deployed_at');}public function fingerprint(ZigoDeployment $deployment):?string{$rows=$deployment->files()->whereNotNull('deployed_fingerprint')->orderBy('relative_path')->get(['relative_path','deployed_fingerprint']);if($rows->isEmpty())return null;$parts=[];foreach($rows as $row){if($this->excluded($row->relative_path))continue;$parts[]=$row->relative_path.':'.$row->deployed_fingerprint;}return$parts===[]?null:hash('sha256',implode("\n",$parts));}private function excluded(string $path):bool{$path='/'.str_replace('\\','/',$path);foreach(['/.env','/storage/','/vendor/','/node_modules/','/.git/'] as $blocked)if(str_starts_with($path,$blocked))return true;return false;}}
